/bin/bash -lc "python - <<'PY'
import json
from pathlib import Path
p=Path('/workspace/run_trace/busco_tool_schema.json')
t=json.loads(p.read_text())

def summarize(inp, indent=0):
    pre='  '*indent
    print(f\"{pre}- {inp.get('name')} type={inp.get('type')} label={inp.get('label') or inp.get('text_value') or ''}\")
    opts=inp.get('options')
    if opts:
        if isinstance(opts, list):
            print(pre+'  options_count', len(opts), 'sample', opts[:8])
        elif isinstance(opts, dict):
            print(pre+'  options keys', list(opts)[:8])
            if 'options' in opts and isinstance(opts['options'], list): print(pre+'  opt sample', opts['options'][:8])
        else: print(pre+'  options type', type(opts).__name__)
    if inp.get('type')=='conditional':
        tp=inp.get('test_param',{})
        print(pre+f\"  test_param {tp.get('name')} type={tp.get('type')} label={tp.get('label')}\")
        if tp.get('options'): print(pre+'  test options', tp.get('options'))
        for case in inp.get('cases', []):
            print(pre+f\"  case value={case.get('value')}\")
            for ci in case.get('inputs', []): summarize(ci, indent+2)
    if inp.get('inputs'):
        for ci in inp.get('inputs'): summarize(ci, indent+1)

print('name', t.get('name'), 'version', t.get('version'))
for inp in t.get('inputs', []): summarize(inp)
print('outputs:')
for out in t.get('outputs', []): print(out)
PY"
